from pathlib import Path
import json,html
p=Path(__file__).parent
results=json.loads((p/'acceptance-results.json').read_text())
files=results['screenshots']
def flow(f):
    if 'existing' in f:return 'Existing place'
    if any(x in f for x in ['copy-unit','three-unit','remove','progress']):return 'Several units'
    if any(x in f for x in ['402','409','save-error','in-progress']):return 'Recovery and drafts'
    return 'One unit'
figures=[]
for f in files:
    device=f.split('-')[0].title();label=f.removesuffix('.png').replace('-',' ')
    figures.append(f'<figure data-device="{device}" data-flow="{flow(f)}"><a href="{f}" target="_blank"><img loading="lazy" src="{f}" alt="{html.escape(label)}"></a><figcaption>{html.escape(label)}</figcaption></figure>')
checks=''.join('<li>'+html.escape(c)+'</li>' for c in results['checks'])
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Restored wizard design</title><style>body{margin:0;background:#fcfbfa;color:#242321;font:16px/1.6 system-ui}header,section,footer{max-width:1100px;margin:auto;padding:30px 24px}h1{font:42px/1.2 Georgia;margin:0 0 16px}a{color:#b52e38}nav{position:sticky;top:0;background:#fff;border-block:1px solid #eee;padding:12px 24px;display:flex;gap:20px;z-index:2}select{font:inherit;padding:8px;border:1px solid #ccc;border-radius:6px}main{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:24px;padding:24px;align-items:start}figure{margin:0;background:white;border:1px solid #e8e2de;border-radius:8px;overflow:hidden}figure img{width:100%;max-height:650px;object-fit:contain;object-position:top;background:white}figcaption{padding:12px;font-size:13px}figure[hidden]{display:none}.note{max-width:800px}</style><header><h1>Wizard acceptance after the transition fix.</h1><p class="note">The saved versionâ€™s illustrations, Playfair headings, warm split layout and unboxed forms surround the real production flow. Mobile keeps the artwork above the question and the actions fixed below.</p><p><a href="http://localhost:8085/create">Click through the local wizard</a> Â· <a href="../wizard-units-v2/one-unit-desktop-place.png">Saved design reference</a></p><p>SCREEN_COUNT screenshots Â· zero uncaught browser errors Â· development data restored Â· no merge.</p></header><nav><label>Size <select id="device"><option>All</option><option>Desktop</option><option>Mobile</option><option>Tablet</option></select></label><label>Flow <select id="flow"><option>All</option><option>One unit</option><option>Several units</option><option>Existing place</option><option>Recovery and drafts</option></select></label></nav><main>FIGURES</main><section><h2>Acceptance checks</h2><ul>CHECKS</ul><p>Normal-motion transition and header geometry checks passed on desktop and mobile. Web, iOS and Android production exports passed. Native device interaction was not tested. Repository TypeScript checking retains 39 existing diagnostics; no new diagnostics were introduced in the restoration modules.</p><p><a href="acceptance-results.json">Full results</a> Â· <a href="restoration.json">Development data restoration</a></p></section><footer>14 November 2026 Â· wizard-units-v2 Â· local review only</footer><script>const device=document.querySelector('#device'),flow=document.querySelector('#flow');function filter(){document.querySelectorAll('figure').forEach(x=>x.hidden=!(device.value==='All'||x.dataset.device===device.value)||!(flow.value==='All'||x.dataset.flow===flow.value))}device.onchange=flow.onchange=filter;</script></html>'''
(p/'index.html').write_text(page.replace('SCREEN_COUNT',str(len(files))).replace('FIGURES',''.join(figures)).replace('CHECKS',checks),encoding='utf8',newline=chr(10))
print(f'Gallery: {len(files)} captures')
